package write_target

import (
	"testing"
	"encoding/base64"

	"github.com/stretchr/testify/require"
)

func TestTxmDevnet(t *testing.T) {
	// Base64-encoded report data (example)
	// version | workflow_execution_id | timestamp | don_id | config_version | ...
	encoded := ""

	// Decode the base64 data
	rawReport, err := base64.StdEncoding.DecodeString(encoded)
	require.NoError(t, err)

	r, err := DecodeReport(rawReport)
	require.NoError(t, err)
	require.Equal(t, uint8(1), r.Version)
	require.Equal(t, "816d80fa4bb8b350cacc3a2e395236bcc6b813b0568b61eea0bd3e6ba7218dd3", r.WorkflowExecutionID)
	require.Equal(t, uint32(1727381360), r.Timestamp)
	require.Equal(t, uint32(0x01), r.DONID)
	require.Equal(t, uint32(0x01), r.ConfigVersion)

	m, err := DecodeMetadata(r.Metadata)
	require.NoError(t, err)
	require.Equal(t, uint16(0x01), m.ReportID)
}
